	vals := wantHeaderKeys(t, m, "Images", "Interrupted")
	if want := "dhi.io, nexus-prod, dev"; vals["Interrupted"] != want {
		t.Errorf("Interrupted = %q, want %q", vals["Interrupted"], want)
	}
}
